import { readFileSync } from "node:fs";

// Let's test the check endpoint with various candidate symbols for n2, n3, n6
const n2_candidates = ["apply_filters", "select_filter", "property_question", "distinguish", "include", "check_reservation_availability", "decision", "change_property", "rank_price"];
const n3_candidates = ["property_question", "attribute_claim", "style_academic", "new_york_university", "reservation_available", "resource_heater", "onsen", "living_room", "bed", "wall", "resource_sink", "reservation_unavailable"];
const n6_candidates = ["new_york_university", "textbook", "style_academic", "africa", "onsen", "locale_en_gb", "foreigners", "resource_heater", "resource_sink", "wall", "liberal_onsen", "state_microwaved"];

EOF

node -e '
const base = (process.env.RAG_URL || `http://host.docker.internal:${process.env.RAG_PORT || "8765"}`).replace(//$/, "");
const needs = JSON.parse(require("fs").readFileSync("/needs.json", "utf8")).needs || JSON.parse(require("fs").readFileSync("/needs.json", "utf8"));

async function test(syms) {
  const table = needs.map((n, i) => `| ${n.id} | ${n.kind} | ${syms[n.id] || "click"} | covered |`).join("
");
  const code = needs.map((n) => syms[n.id] || "click").join(", ");
  const md = `Status: success
Mode: TRACE

## BrainCode

\`\`\`braincode
MODE TRACE
ENTRYPOINT Conversation
CONVO Conversation {
  TURN t1 SPEAKER=USER {
    # ${code}
  }
}
\`\`\`

## Needs coverage

| need | kind | expressed by | status |
|---|---|---|---|
${table}

## Translation report
- Input kind: conversation
- Coverage status: complete
- Source-span coverage: all
- Opaque-text spans: none
- Label-preserved spans: none
- Missing constructs: none
- Unresolved ambiguities: none
`;
  const res = await fetch(base + "/check", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ translation: md, needs }) });
  return await res.text();
}

(async () => {
  for (const n of ["n2", "n3", "n6"]) {
    console.log("=== Testing " + n + " ===");
    const cand = needs.find(x => x.id === n).candidates || [];
    for (const c of cand) {
      const res = await test({ [n]: c.symbol });
      const line = res.split("
").find(l => l.includes(n));
      console.log(`${c.symbol}: ${line}`);
    }
  }
})();
'

